// ---------------------------------------------------------------------------
// UC2-S2: Cell size is configurable — gridTemplateColumns reflects cellSize
// (was ⚠️ partial: CSS vars asserted but computed template not asserted)
// ---------------------------------------------------------------------------
describe('DashboardGrid — cellSize configurable (UC2-S2)', () => {
  it('UC2-S2: gridTemplateColumns uses the provided cellSize', () => {
    const { container } = render(
      <DashboardGrid cols={4} rows={3} cellSize={80} initialLayout={[]} />
    );
    const grid = container.firstChild as HTMLElement;
    expect(grid.style.gridTemplateColumns).toBe('repeat(4, 80px)');
    expect(grid.style.gridTemplateRows).toBe('repeat(3, 80px)');
  });
});

