// ---------------------------------------------------------------------------
// UC1-S7/S8: Widget rendered at new position after layout state update
// (was ❌: new position CSS not asserted after drop)
// ---------------------------------------------------------------------------
describe('DashboardGrid — widget at new position after layout update (UC1-S7, UC1-S8)', () => {
  it('UC1-S7: widget CSS reflects updated x,y when controlled layout changes', () => {
    const layout1: WidgetLayout[] = [{ id: 'a', x: 0, y: 0, w: 1, h: 1 }];
    const layout2: WidgetLayout[] = [{ id: 'a', x: 3, y: 2, w: 1, h: 1 }];

    const { rerender } = render(
      <DashboardGrid cols={6} rows={4} cellSize={100} initialLayout={[]} layout={layout1} onLayoutChange={() => {}} />
    );
    expect(screen.getByTestId('widget-a').style.gridColumn).toBe('1 / span 1');
    expect(screen.getByTestId('widget-a').style.gridRow).toBe('1 / span 1');

    rerender(
      <DashboardGrid cols={6} rows={4} cellSize={100} initialLayout={[]} layout={layout2} onLayoutChange={() => {}} />
    );
    // After layout update widget 'a' should be at col 4, row 3
    expect(screen.getByTestId('widget-a').style.gridColumn).toBe('4 / span 1');
    expect(screen.getByTestId('widget-a').style.gridRow).toBe('3 / span 1');
  });

  it('UC1-S8: non-moved widgets retain their position when another widget moves', () => {
    const layout1: WidgetLayout[] = [
      { id: 'a', x: 0, y: 0, w: 1, h: 1 },
      { id: 'b', x: 2, y: 0, w: 1, h: 1 },
    ];
    const layout2: WidgetLayout[] = [
      { id: 'a', x: 4, y: 2, w: 1, h: 1 }, // 'a' moved
      { id: 'b', x: 2, y: 0, w: 1, h: 1 }, // 'b' unchanged
    ];
    const { rerender } = render(
      <DashboardGrid cols={6} rows={4} cellSize={100} initialLayout={[]} layout={layout1} onLayoutChange={() => {}} />
    );
    rerender(
      <DashboardGrid cols={6} rows={4} cellSize={100} initialLayout={[]} layout={layout2} onLayoutChange={() => {}} />
    );
    // 'b' still at col 3
    expect(screen.getByTestId('widget-b').style.gridColumn).toBe('3 / span 1');
    expect(screen.getByTestId('widget-b').style.gridRow).toBe('1 / span 1');
  });
});

