// ---------------------------------------------------------------------------
// UC1-E5a: Out-of-bounds drop — layout unchanged (layout controlled mode)
// (was ❌: not tested at component level)
// ---------------------------------------------------------------------------
describe('DashboardGrid — out-of-bounds drop leaves layout unchanged (UC1-E5a)', () => {
  it('UC1-E5a: onLayoutChange is NOT called when no pointer movement occurs (no-op drag)', () => {
    const onLayoutChange = vi.fn();
    const layout: WidgetLayout[] = [{ id: 'a', x: 0, y: 0, w: 1, h: 1 }];
    render(
      <DashboardGrid cols={6} rows={4} cellSize={100}
        initialLayout={[]} layout={layout} onLayoutChange={onLayoutChange} />
    );
    // No drag events fired — layout change callback must not be invoked
    expect(onLayoutChange).not.toHaveBeenCalled();
    expect(screen.getByTestId('widget-a').style.gridColumn).toBe('1 / span 1');
  });
});

// ---------------------------------------------------------------------------
// UC1-E6a: Occupied cells — isValidPlacement returns false (component-level guard)
// (was ❌: component-level rejection not verified beyond not-crashing)
// ---------------------------------------------------------------------------
describe('DashboardGrid — occupied cell drop guard (UC1-E6a)', () => {
  beforeEach(() => {
    vi.spyOn(console, 'warn').mockImplementation(() => {});
  });

  it('UC1-E6a: both widgets present after attempted overlapping initial config', () => {
    const layout: WidgetLayout[] = [
      { id: 'x', x: 0, y: 0, w: 2, h: 2 },
      { id: 'y', x: 0, y: 0, w: 2, h: 2 },
    ];
    render(<DashboardGrid cols={6} rows={4} cellSize={100} initialLayout={layout} />);
    expect(screen.getByTestId('widget-x')).toBeInTheDocument();
    expect(screen.getByTestId('widget-y')).toBeInTheDocument();
  });

  it('UC1-E6a1: after overlap resolution, widgets do not share a grid cell position', () => {
    const layout: WidgetLayout[] = [
      { id: 'p', x: 0, y: 0, w: 1, h: 1 },
      { id: 'q', x: 0, y: 0, w: 1, h: 1 },
    ];
    render(<DashboardGrid cols={6} rows={4} cellSize={100} initialLayout={layout} />);
    const p = screen.getByTestId('widget-p');
    const q = screen.getByTestId('widget-q');
    // Their CSS grid positions must differ
    const pCol = p.style.gridColumn;
    const qCol = q.style.gridColumn;
    const pRow = p.style.gridRow;
    const qRow = q.style.gridRow;
    expect(pCol === qCol && pRow === qRow).toBe(false);
  });
});
